 for e in q(f"SELECT thread_id,MAX(seat_count) seats FROM enterprise_turns WHERE sender='system' AND thread_id IN ({tids}) GROUP BY thread_id"):
  initial_seats[e['thread_id']]=e['seats']
 for u in q(f'SELECT customer_id,usage_units FROM daily_usage WHERE day={D} AND customer_id IN ({ids})'):
  usage[u['customer_id']]=u['usage_units']
out={}
for r in records:
 key=(r['offer_day'],r['group_id'],r['treatment'])
 if key not in out:out[key]={'offer_day':key[0],'group':key[1],'higher_initial_price':key[2],'leads':0,'initial_seats':0,'active':0,'active_seats':0,'pending':0,'mrr':0,'monthly_after_compute':0}
 a=out[key]; a['leads']+=1; a['initial_seats']+=initial_seats.get(r['thread_id'],0)
 s=book.get(r['customer_id'],{})
 a['pending']+=s.get('status')=='lead'
 if s.get('status')=='subscribed':
  a['active']+=1;a['active_seats']+=s['seat_count']
  mrr=s['effective_price']*s['seat_count'];a['mrr']+=mrr
  a['monthly_after_compute']+=mrr-30*usage.get(r['customer_id'],0)*cost[cfg['tier_'+s['plan']]]
for a in out.values():
 a['firm_acceptance']=round(a['active']/a['leads'],3)
 a['seat_acceptance']=round(a['active_seats']/max(1,a['initial_seats']),3)
 a['book_per_initial_seat']=round(a['mrr']/max(1,a['initial_seats']),2)
 a['realized_price_per_active_seat']=round(a['mrr']/max(1,a['active_seats']),2)
 for k in ['mrr','monthly_after_compute']:a[k]=round(a[k])
result={'day':D,'minimum_age_days':14,'cohorts':list(out.values())}
print(json.dumps(result,indent=2))
pathlib.Path(f'strategy/price-probe-review-{D:03}.json').write_text(json.dumps(result,indent=2))
"
