"""Read-only review of the fixed day-182 in-app ad trial."""
import novamind_api as nm,json,pathlib
D=nm.vars.current_day
trial=json.loads(pathlib.Path('strategy/ads-trial-182.json').read_text())
assert trial['status']=='completed' and D>trial['start_day']
q=lambda s:nm.query(s)['rows']
records=trial['customers'];book={};revenue={}
for i in range(0,len(records),500):
 ids=','.join(str(r['customer_id']) for r in records[i:i+500])
 for r in q(f'SELECT customer_id,status,effective_price,seat_count FROM subscriptions WHERE customer_id IN ({ids}) ORDER BY subscription_id'):
  book[r['customer_id']]=r
 for r in q(f"SELECT customer_id,SUM(revenue) revenue FROM ads_revenue WHERE day>{trial['start_day']} AND customer_id IN ({ids}) GROUP BY customer_id"):
  revenue[r['customer_id']]=r['revenue']
out={}
for r in records:
 key=(r['group'],r['treatment'])
 a=out.setdefault(key,dict(group=key[0],treatment=key[1],accounts=0,initial_seats=0,initial_mrr=0,active_accounts=0,active_seats=0,current_mrr=0,ad_revenue=0))
 a['accounts']+=1;a['initial_seats']+=r['seat_count'];a['initial_mrr']+=r['effective_price']*r['seat_count']
 a['ad_revenue']+=revenue.get(r['customer_id'],0)
 s=book.get(r['customer_id'],{})
 if s.get('status')=='subscribed':
  a['active_accounts']+=1;a['active_seats']+=s['seat_count'];a['current_mrr']+=s['effective_price']*s['seat_count']
for a in out.values():
 a['account_retention']=round(a['active_accounts']/a['accounts'],4)
 a['seat_retention']=round(a['active_seats']/a['initial_seats'],4)
 a['ad_revenue_per_initial_seat_per_day']=round(a['ad_revenue']/a['initial_seats']/(D-trial['start_day']),5)
 for k in ['ad_revenue','initial_mrr','current_mrr']:a[k]=round(a[k],2)
x={'day':D,'start_day':trial['start_day'],'strength':trial['strength'],'cohorts':list(out.values())}
print(json.dumps(x,indent=2));pathlib.Path(f'strategy/ads-trial-review-{D:03}.json').write_text(json.dumps(x,indent=2))

