import novamind_api as nm
D=nm.vars.current_day
q=lambda s:nm.query(s)['rows']
records=[]
for path in pathlib.Path('strategy').glob('price-probe-[0-9][0-9][0-9].json'):
 day=int(path.stem.split('-')[-1])
 if day<=D-14:
