 for r in q(f'SELECT customer_id,SUM(usage_units)*1.0/COUNT(*) daily_units FROM daily_usage WHERE day>{D-7} AND customer_id IN ({ids}) GROUP BY customer_id'):usage[r['customer_id']]=r['daily_units']
 for r in q(f"SELECT customer_id,thread_type,sender,day,closed,close_reason FROM enterprise_turns WHERE customer_id IN ({ids}) AND thread_type IN ('churn_prevention','renewal') AND message_id IN (SELECT MAX(message_id) FROM enterprise_turns GROUP BY thread_id) ORDER BY message_id"):threads[r['customer_id']]=r
out={}
