 if s.get('status')=='subscribed':
  a['active_firms']+=1;a['active_seats']+=s['seat_count'];a['mrr']+=s['effective_price']*s['seat_count'];a['plan_A']+=s['plan']=='A';a['plan_C']+=s['plan']=='C';a['pending_A']+=s.get('pending_plan')=='A'
  a['monthly_run_rate_after_compute']+=s['effective_price']*s['seat_count']-30*usage.get(r['customer_id'],0)*cost[cfg['tier_'+s['plan']]]
x={'day':D,'start_day':224,'groups':list(out.values()),'caveat':'Contribution applies current plan cost to recent average usage as a forward run-rate estimate. Billing stays suspended during open churn-prevention threads; MRR is not actual cash collected.'}
