{
  "/workspace/local/workspace/run-ceobench/strategy/review_retention_cohorts.py": {
    "type": "add",
    "content": """"Read-only retention review, assigning each firm to its first menu cohort."""
import novamind_api as nm,json,pathlib
D=nm.vars.current_day
q=lambda s:nm.query(s)['rows']
records={}
for path in sorted(pathlib.Path('strategy').glob('retention-menu-*.json')):
 trial=json.loads(path.read_text())
 if trial['day']>=D or trial['status']!='completed':continue
 for r in trial['customers']:
  if r['customer_id'] not in records:records[r['customer_id']]={**r,'first_menu_day':trial['day']}
assert records,'No completed earlier retention cohorts'
cfg=q('SELECT * FROM config_history ORDER BY day DESC LIMIT 1')[0]
cost={1:.0003,2:.002,3:.006,4:.012,5:.03}
book={};usage={};threads={};ids_all=sorted(records)
for i in range(0,len(ids_all),400):
 ids=','.join(str(cid) for cid in ids_all[i:i+400])
 for r in q(f'SELECT customer_id,status,plan,effective_price,seat_count,pending_plan,pending_price,billing_day_mod30 FROM subscriptions WHERE customer_id IN ({ids}) ORDER BY subscription_id'):book[r['customer_id']]=r
 for r in q(f'SELECT customer_id,SUM(usage_units)*1.0/COUNT(*) daily_units FROM daily_usage WHERE day>{D-7} AND customer_id IN ({ids}) GROUP BY customer_id'):usage[r['customer_id']]=r['daily_units']
 for r in q(f"SELECT customer_id,thread_type,sender,day,closed,close_reason FROM enterprise_turns WHERE customer_id IN ({ids}) AND thread_type IN ('churn_prevention','renewal') AND message_id IN (SELECT MAX(message_id) FROM enterprise_turns GROUP BY thread_id) ORDER BY message_id"):threads[r['customer_id']]=r
out={}
for cid,r in records.items():
 key=(r['first_menu_day'],r['group'])
 a=out.setdefault(key,{'first_menu_day':key[0],'group':key[1],'firms0':0,'seats0':0,'mrr0':0,'active_firms':0,'active_seats':0,'mrr':0,'monthly_run_rate_after_compute':0,'plan_A':0,'plan_C':0,'pending_A':0,'latest_accepted':0,'open_retention':0,'suspended_mrr':0,'scheduled_invoices_next7':0,'at_risk_invoices_next7':0})
 a['firms0']+=1;a['seats0']+=r['seats'];a['mrr0']+=r['seats']*r['old_price']
 s=book.get(cid,{});t=threads.get(cid,{})
 if s.get('status')!='subscribed':continue
 mrr=s['effective_price']*s['seat_count'];at_risk=t.get('closed')==0
 due=1<=(s['billing_day_mod30']-D%30+30)%30<=7
 a['active_firms']+=1;a['active_seats']+=s['seat_count'];a['mrr']+=mrr
 a['monthly_run_rate_after_compute']+=mrr-30*usage.get(cid,0)*cost[cfg['tier_'+s['plan']]]
 a['plan_A']+=s['plan']=='A';a['plan_C']+=s['plan']=='C';a['pending_A']+=s.get('pending_plan')=='A'
 a['latest_accepted']+=t.get('close_reason')=='accepted';a['open_retention']+=at_risk
 a['suspended_mrr']+=mrr if at_risk else 0
 a['scheduled_invoices_next7']+=mrr if due else 0
 a['at_risk_invoices_next7']+=mrr if due and at_risk else 0
groups=list(out.values());totals={k:sum(r[k] for r in groups) for k in groups[0] if k not in ['first_menu_day','group']}
x={'day':D,'totals':totals,'groups':groups,'caveat':'A firm is assigned once, at its first menu. Subscription MRR is not collected cash. Open retention discussions suspend bills. Current-plan compute on recent average units is a forward estimate, not historical individual ledger cost.'}
pathlib.Path(f'strategy/retention-cohorts-review-{D:03}.json').write_text(json.dumps(x,indent=2))
print(json.dumps(x,indent=2))
"
  }
}

