/bin/bash -lc "python - <<'PY'
import json,pathlib
x=json.load(open('strategy/summary-238.json'))
for k in ['cash','flows','issues','enterprise','news']:print(k,json.dumps(x[k]))
cs={}
for r in x['cohorts']:
 if r['group_id'].startswith(('S','D_S')):
  a=cs.setdefault(r['group_id'],[0,0]);a[0]+=r['n'];a[1]+=r['n'] if r['status']=='subscribed' else 0
print('CONVERSION',{g:round(a[1]/max(1,a[0]),3) for g,a in cs.items()})
p=pathlib.Path('strategy/CURRENT_STATE.json');s=json.loads(p.read_text());s['last_confirmed_cash']=x['cash'];s.pop('last_cash_is_dashboard_rounded',None);p.write_text(json.dumps(s,indent=2))
PY"

