{
  "/workspace/local/workspace/run-ceobench/strategy/support_economics.py": {
    "type": "add",
    "content": """"Read-only current-plan contribution including approximate marginal support."""
import novamind_api as nm,json,pathlib
D=nm.vars.current_day
x=json.load(open(f'strategy/plan-economics-{D:03}.json'));assert x['day']==D
rows=nm.query(f"SELECT c.group_id,s.plan,COUNT(*) new_issues FROM issues i JOIN customers c USING(customer_id) JOIN subscriptions s USING(customer_id) WHERE i.open_day={D} AND s.status='subscribed' GROUP BY c.group_id,s.plan")['rows']
issues={(r['group_id'],r['plan']):r['new_issues'] for r in rows}
out=[]
for r in x['groups']:
 n=issues.get((r['group_id'],r['plan']),0)
 monthly_ops=30*n/(.3 if r['customer_type']=='small' else .05)
 out.append({'group':r['group_id'],'plan':r['plan'],'n':r['n'],'seats':r['seats'],'new_issues':n,'issues_per_account':n/max(1,r['n']),'monthly_revenue_per_seat':r['monthly_revenue_per_seat'],'monthly_compute_per_seat':r['monthly_compute_per_seat'],'monthly_issue_resolution_cost_per_seat':monthly_ops/max(1,r['seats']),'monthly_after_compute_and_issue_resolution_per_seat':r['monthly_revenue_per_seat']-r['monthly_compute_per_seat']-monthly_ops/max(1,r['seats'])})
y={'day':D,'groups':out,'caveat':'Approximate marginal support cost uses documented .3 retail or .05 enterprise issues resolved per dollar. Current-day new issues and current plan assignments; actual budgets include buffers and global pool allocation, development and capacity excluded.'}
pathlib.Path(f'strategy/support-economics-{D:03}.json').write_text(json.dumps(y,indent=2));print(json.dumps(y,indent=2))
"
  }
}

