 key=(r['offer_day'],r['group_id'],r['treatment'],phase,base)
 if key not in out:out[key]={'offer_day':key[0],'group':key[1],'higher_initial_price':key[2],'menu_phase':phase,'base_price':base,'age_days':D-r['offer_day'],'leads':0,'initial_seats':0,'active':0,'active_seats':0,'pending':0,'mrr':0,'monthly_after_compute':0,'active_A':0,'active_C':0,'suspended_mrr':0}
 a=out[key]; a['leads']+=1; a['initial_seats']+=initial_seats.get(r['thread_id'],0)
