    "content": """"Observe first retail renewals for post-rescue signup cohorts, from public SQL."""
import json,pathlib
import novamind_api as nm
D=nm.vars.current_day
rows=[]
if D>=255:
 rows=nm.query(f"""+WITH latest AS (
 SELECT s.customer_id,MAX(s.subscription_id) sid
 FROM subscriptions s JOIN customers c USING(customer_id)
 WHERE c.customer_type='small' AND c.created_day BETWEEN 225 AND {D-30}
 GROUP BY s.customer_id
)
SELECT c.group_id,c.created_day,s.status,s.plan,COUNT(*) n,
 SUM(CASE WHEN s.status='subscribed' THEN s.effective_price ELSE 0 END) current_mrr,
 SUM(CASE WHEN s.status='cancelled' AND s.end_day<=c.created_day+30 THEN 1 ELSE 0 END) cancelled_by_first_renewal,
 SUM(CASE WHEN s.status IN ('subscribed','cancelled') AND s.start_day!=c.created_day THEN 1 ELSE 0 END) start_day_differs
FROM latest l JOIN customers c USING(customer_id) JOIN subscriptions s ON s.subscription_id=l.sid
GROUP BY c.group_id,c.created_day,s.status,s.plan
ORDER BY c.created_day,c.group_id,s.status,s.plan
""")['rows']
groups={}
for r in rows:
 if r['status'] not in ('subscribed','cancelled'):continue
 key=(r['group_id'],r['created_day'])
 if key not in groups:groups[key]={'group':key[0],'signup_day':key[1],'age_days':D-key[1],'initial_subscribers':0,'first_renewal_losses':0,'current_active':0,'current_mrr':0,'start_day_differs':0}
 a=groups[key];a['initial_subscribers']+=r['n'];a['first_renewal_losses']+=r['cancelled_by_first_renewal'];a['current_active']+=r['n'] if r['status']=='subscribed' else 0;a['current_mrr']+=r['current_mrr'];a['start_day_differs']+=r['start_day_differs']
for a in groups.values():a['first_renewal_loss_rate']=a['first_renewal_losses']/a['initial_subscribers']
x={'day':D,'cohorts':list(groups.values()),'current_plan_status_rows':rows,'caveat':'Latest public subscription per customer, signup cohorts created225 onward with at least30days elapsed. Initial conversion reconstructed from subscribed/cancelled statuses. Current plan is not a stored initial-plan assignment. Inspect start_day_differs before interpreting first-renewal counts; price/research/market conditions differ across cohorts.'}
pathlib.Path(f'strategy/first-renewal-review-{D:03}.json').write_text(json.dumps(x,indent=2));print(json.dumps(x,indent=2))
