"""One weekly decision cycle using only documented SDK and public SQL observations.
No retries. A local start marker prevents rerunning an uncertain cycle.
"""
import json, math, pathlib, runpy, contextlib, io
import novamind_api as nm
from novamind_api._client import next_week
q=lambda s:nm.query(s)['rows']
D=nm.vars.current_day
assert D<500
policy=json.load(open('strategy/policy.json'))
assert D==policy['expected_day'], 'Expected-day guard mismatch'
marker=pathlib.Path(f'strategy/turn-{D:03}-started.json')
assert not marker.exists(), 'Cycle already started; inspect request status, never replay.'
# Read and analyze before changing any setting.
with contextlib.redirect_stdout(io.StringIO()):runpy.run_path('strategy/compact.py')
x=json.load(open(f'strategy/summary-{D:03}.json'))
print('OBSERVED',json.dumps({k:x[k] for k in ['day','cash','flows','groups','churn','usage']}),flush=True)
print('ISSUE_AGES',json.dumps([r for r in x['issues'] if r['age']>1]),flush=True)
print('MARKET_NEWS',json.dumps(x['news']),flush=True)
cfg=q('SELECT * FROM config_history ORDER BY day DESC LIMIT 1')[0]
old=q("SELECT settings_json FROM config_overrides WHERE setting_type='targeted_ad_spend' ORDER BY id DESC LIMIT 1")
adcfg=json.loads(old[0]['settings_json']) if old else {}
oldads=adcfg.get('targeted_spend',adcfg)
oldgroup={}
for ch,gs in oldads.items():
 if isinstance(gs,dict):
  for g,v in gs.items():oldgroup[g]=oldgroup.get(g,0)+float(v)
co=q(f"SELECT c.group_id,COUNT(*) leads,SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) converted,SUM(CASE WHEN s.status='subscribed' THEN s.effective_price ELSE 0 END) new_mrr,SUM(CASE WHEN c.acquisition_source NOT IN ('network','word_of_mouth') AND s.status='subscribed' THEN 1 ELSE 0 END) paid_converted,SUM(CASE WHEN c.acquisition_source NOT IN ('network','word_of_mouth') THEN 1 ELSE 0 END) paid_leads FROM customers c JOIN subscriptions s USING(customer_id) WHERE c.created_day>{D-7} AND c.customer_type='small' GROUP BY c.group_id")
co={r['group_id']:r for r in co}
book={r['group_id']:r for r in x['groups']}
retail={g:r for g,r in book.items() if g.startswith('S') or g.startswith('D_S')}
n=sum(r['n'] for r in retail.values())
new=sum(r['new'] for r in retail.values())
flows={r['category']:r['amount'] for r in x['flows']}
usage=q(f"SELECT c.group_id,SUM(u.usage_units*CASE s.plan WHEN 'A' THEN {dict([(1,.0003),(2,.002),(3,.006),(4,.012),(5,.03)])[cfg['tier_A']]} WHEN 'B' THEN {dict([(1,.0003),(2,.002),(3,.006),(4,.012),(5,.03)])[cfg['tier_B']]} ELSE {dict([(1,.0003),(2,.002),(3,.006),(4,.012),(5,.03)])[cfg['tier_C']]} END) cost FROM daily_usage u JOIN customers c USING(customer_id) JOIN subscriptions s USING(customer_id) WHERE u.day={D} AND s.status='subscribed' GROUP BY c.group_id")
uc={r['group_id']:r['cost'] for r in usage}
observed_ads={}
for r in x['ads']:observed_ads[r['group_id']]=observed_ads.get(r['group_id'],0)+r['spend']
plan_projection={}
support_path=pathlib.Path(f'strategy/support-economics-{D:03}.json')
plan_path=pathlib.Path(f'strategy/plan-economics-{D:03}.json')
if support_path.exists() and plan_path.exists():
 support_data=json.loads(support_path.read_text());plan_data=json.loads(plan_path.read_text())
 assert support_data['day']==D and plan_data['day']==D
 support_rows={(r['group'],r['plan']):r for r in support_data['groups']}
 for g in retail:
  plans=[r for r in plan_data['groups'] if r['group_id']==g]
  use_new=sum(r['new_n'] for r in plans)>=50
  denominator=sum(r['new_n'] if use_new else r['n'] for r in plans)
  if denominator:
   compute=sum((r['new_n'] if use_new else r['n'])*r['monthly_compute_per_seat'] for r in plans)/denominator
   support=sum((r['new_n'] if use_new else r['n'])*support_rows[(g,r['plan'])]['monthly_issue_resolution_cost_per_seat'] for r in plans)/denominator
   plan_projection[g]={'compute':compute,'support':support,'basis':'recent_signup_plan_mix' if use_new else 'current_book_plan_mix'}
chosen={}; analysis=[]
blocked=set(policy.get('blocked_ads',['S1','S3']))
for g,r in retail.items():
 c=co.get(g,{});conv=c.get('converted',0)/max(1,c.get('leads',0))
 arpu=c.get('new_mrr',0)/max(1,c.get('converted',0)) if c.get('converted',0)>50 else r['mrr']/max(1,r['n'])
 monthly_margin=arpu-30*(uc.get(g,0)/max(1,r['n'])+(cfg['spend_operations']+37500)/max(n,1))
 if g in plan_projection:
  # Plan A now has materially higher compute than legacy B/C. Weight
  # observed plan costs by recent signups and include marginal support,
  # instead of valuing new customers at the legacy mixed-book average.
  est=plan_projection[g]
  monthly_margin=arpu-est['compute']-1.2*est['support']-30*37500/max(n,1)
 paid=c.get('paid_converted',0);cac=(observed_ads.get(g,0)+.5*c.get('paid_leads',0))/max(1,paid)
 oldspend=oldgroup.get(g,0)
 spend=oldspend
 if g in blocked:spend=0
 elif oldspend:
  if conv<.12 or monthly_margin<=0:spend=0
  elif cac<monthly_margin*.75:spend*=1.7
  elif cac<monthly_margin*1.5:spend*=1.2
  elif cac>monthly_margin*3:spend*=.4
  elif cac>monthly_margin*2:spend*=.7
  if paid<500 and oldspend>50000:spend=min(spend,oldspend*.5)
  group_churn=sum(z['n'] for z in x['churn'] if z['group_id']==g)
  if r['n']>50000 and paid<r['n']*.05 and c.get('converted',0)-paid>group_churn and cac>monthly_margin*1.5:spend=0
 elif conv>=.35 and monthly_margin>=12 and r['n']<100000:spend=policy.get('probe_spend',5000)
 spend=min(policy.get('max_group_ad',150000),spend)
 if spend>=1000:chosen[g]=round(spend/1000)*1000
 analysis.append({'group':g,'conversion':round(conv,3),'arpu':round(arpu,1),'gross_monthly_margin':round(monthly_margin,1),'margin_basis':plan_projection.get(g,{}).get('basis','legacy_mixed_book_fallback'),'monthly_compute':round(plan_projection[g]['compute'],1) if g in plan_projection else None,'monthly_issue_resolution':round(plan_projection[g]['support'],1) if g in plan_projection else None,'paid_cac':round(cac,1) if oldspend else None,'old_ad':oldspend,'new_ad':spend})
for g,v in policy.get('ad_overrides',{}).items():
 if v>0:chosen[g]=v
 else:chosen.pop(g,None)
maxads=min(policy.get('max_total_ad',600000),x['cash']/21,max(50000,flows.get('subscription_payment',0)/7*.4))
if sum(chosen.values())>maxads:
 factor=maxads/sum(chosen.values());chosen={g:math.floor(v*factor/1000)*1000 for g,v in chosen.items() if v*factor>=1000}
created=q(f"SELECT c.group_id,COUNT(*) n FROM issues i JOIN customers c USING(customer_id) WHERE i.open_day>{D-7} AND c.customer_type='small' GROUP BY c.group_id")
created_daily=sum(r['n'] for r in created)/7
recent_churn=sum(r['n'] for r in x['churn'] if r['group_id'] in retail)
growth=max(0,new-recent_churn)/max(1,n)
ops=math.ceil(max(1500,created_daily*(policy.get('ops_buffer',1.15)+growth)/.3)/1000)*1000
if any(r['age']>2 for r in x['issues'] if r['group_id'] in retail):ops=math.ceil(ops*1.15/1000)*1000
if policy.get('operations_override_day',D)==D:ops=policy.get('operations_override',ops)
entops={g:max(100,math.ceil(r['n']*policy.get('enterprise_ops_per_firm',3)/100)*100) for g,r in book.items() if g not in retail and r['n']>0}
if policy.get('enterprise_ops_basis')=='observed_issues':
 assert support_path.exists() and plan_path.exists(), 'Observed enterprise support requires current plan and support economics'
 detail_path=pathlib.Path(f'strategy/detail-{D:03}.json')
 assert detail_path.exists(), 'Observed enterprise support requires current weekly details'
 detail=json.loads(detail_path.read_text());assert detail['day']==D
 latest_issues={}
 for r in support_data['groups']:
  latest_issues[r['group']]=latest_issues.get(r['group'],0)+r['new_issues']
 week_issues={r['group_id']:r['n']/7 for r in detail['enterprise_week_issues']}
 # Independent targeted pools retain a 20% buffer; half the last-week mean
 # cushions sudden declines. The global pool provides additional coverage.
 entops={g:max(100,math.ceil(max(latest_issues.get(g,0),week_issues.get(g,0)*.5)*1.2/.05/100)*100) for g in entops}
for r in x['issues']:
 g=r['group_id']
 if g not in retail and r['age']>2:entops[g]=max(entops.get(g,0),r['n']*20)
strategy={'day':D,'cash':x['cash'],'groups':analysis,'ads':chosen,'operations':ops,'enterprise_ops':entops,'retail_issues_per_day':round(created_daily)}
print('WEEKLY_ANALYSIS',json.dumps(strategy),flush=True)
marker.write_text(json.dumps(strategy,indent=2))
print(nm.marketing.set_targeted_ad_spend({'referral_program':chosen}),flush=True)
print(nm.marketing.set_daily_spend(operations=ops,development=policy.get('global_development',cfg['spend_development'])),flush=True)
print(nm.analytics.set_targeted_ops_spend(by_group=entops),flush=True)
if 'targeted_development' in policy:
 prev=q("SELECT settings_json FROM config_overrides WHERE setting_type='targeted_dev_spend' ORDER BY id DESC LIMIT 1")
 prev=json.loads(prev[0]['settings_json']).get('targeted_spend',{}) if prev else {}
 if prev!=policy['targeted_development']:print(nm.analytics.set_targeted_dev_spend(policy['targeted_development']),flush=True)
if 'prices' in policy:print(nm.pricing.set_prices(**policy['prices']),flush=True)
if 'tiers' in policy:print(nm.pricing.set_model_tiers(**policy['tiers']),flush=True)
if 'quotas' in policy:print(nm.pricing.set_usage_quotas(**{k:policy['quotas'].get(k,cfg['quota_'+k]) for k in ['A','B','C']}),flush=True)
if 'social_post' in policy and policy.get('social_post_day',D)==D:print(nm.marketing.post_social_media(**policy['social_post']),flush=True)
runpy.run_path('strategy/promotions.py')
runpy.run_path('strategy/deals.py')
if policy.get('renegotiate',False):runpy.run_path('strategy/renegotiate.py')
# Forecast from public recurring book, recent operating flows, and planned spending.
mrr=sum(r['mrr'] for r in book.values())
net=sum(v for k,v in flows.items() if k not in ('research_project','group_research','market_research','initial_funding'))
net-=7*(sum(chosen.values())-sum(oldgroup.values())+ops-cfg['spend_operations'])
base_profit=mrr*7/30+sum(v for k,v in flows.items() if v<0 and k not in ('research_project','group_research','market_research','initial_funding'))
base_profit-=7*(sum(chosen.values())-sum(oldgroup.values())+ops-cfg['spend_operations'])
new_mrr=sum(r.get('new_mrr',0) for r in co.values())
preds={}
for k,h in [('cash_1wk',7),('cash_4wk',28),('cash_12wk',84),('cash_26wk',182)]:
 weeks=min(h,500-D)/7
 point=x['cash']+net*min(weeks,4)+max(base_profit,net*.6)*max(weeks-4,0)+new_mrr*.025*min(weeks,12)**2
 point=max(0,point)
 spread=max(500000,abs(point-x['cash'])*(.30 if h==7 else .5 if h==28 else .7),x['cash']*(.06 if h==7 else .10 if h==28 else .2))
 preds[k]={'point':point,'lower':max(0,point-spread),'upper':point+spread}
if 'forecasts' in policy and policy.get('forecast_day',D)==D:
 preds={k:dict(zip(['point','lower','upper'],policy['forecasts'][i*3:i*3+3])) for i,k in enumerate(preds)}
rationale=f"Day {D}: cash ${x['cash']:,.0f}, recurring monthly book ${mrr:,.0f}, {n} retail customers, last operating cash ${sum(v for k,v in flows.items() if k not in ('research_project','group_research','market_research','initial_funding')):,.0f}. Recomputed paid acquisition cost, conversion and contribution by segment; scaled ads with short payback and cut inefficient channels. Selected daily referral spend {chosen}. Set operations {ops} and enterprise support {entops} based on installed base, recent growth and issue age. Responded to enterprise threads. {policy.get('rationale','Maintain quality investment and watch churn, saturation and cash payback.') }"
print('ADVANCE_PLAN',json.dumps({'rationale':rationale,'forecasts':preds}),flush=True)
r=next_week(predictions=preds,rationale=rationale,request_id=f'week-{D//7+1:03}')
pathlib.Path(f'strategy/advance-{D:03}.json').write_text(json.dumps(r,indent=2))
def show(x):
 if isinstance(x,dict):
