"""Public contract billing projection after current recurring promotions apply."""
import json,pathlib
import novamind_api as nm
D=nm.vars.current_day
cfg=nm.query("SELECT settings_json FROM config_overrides WHERE setting_type='promotion' ORDER BY id DESC LIMIT 1")['rows']
p=json.loads(cfg[0]['settings_json']) if cfg else {}
assert not p.get('by_customer'), 'Individual coupons need explicit projection support'
lit=lambda x:"'"+str(x).replace("'","''")+"'"
discount=[str(float(p.get('global',0)))]
for g,v in p.get('by_group',{}).items():discount.append(f"CASE WHEN c.group_id={lit(g)} THEN {float(v)} ELSE 0 END")
for g,plans in p.get('by_group_plan',{}).items():
 for plan,v in plans.items():discount.append(f"CASE WHEN c.group_id={lit(g)} AND s.plan={lit(plan)} THEN {float(v)} ELSE 0 END")
expected="CASE WHEN c.customer_type='small' THEN MAX(0,s.listed_price-("+'+'.join(discount)+")) ELSE s.effective_price END"
due=f'((s.billing_day_mod30-{D}%30+30)%30) BETWEEN 1 AND 7'
rows=nm.query(f"SELECT c.group_id,s.plan,COUNT(*) n,SUM(s.effective_price*s.seat_count) current_mrr,SUM(({expected})*s.seat_count) projected_mrr,SUM(CASE WHEN {due} THEN s.effective_price*s.seat_count ELSE 0 END) current_scheduled_7d,SUM(CASE WHEN {due} THEN ({expected})*s.seat_count ELSE 0 END) projected_scheduled_7d,SUM(CASE WHEN ({expected})!=s.effective_price THEN 1 ELSE 0 END) price_changes_at_bill FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' GROUP BY c.group_id,s.plan")['rows']
totals={k:sum(r[k] for r in rows) for k in ['current_mrr','projected_mrr','current_scheduled_7d','projected_scheduled_7d','price_changes_at_bill']}
x={'day':D,'totals':totals,'groups':rows,'caveat':'Applies current recurring coupons to locked listed prices for retail. Enterprise current prices carried forward. Excludes future churn, plan changes, new signups and retention billing suspensions; not a collections forecast.'}
pathlib.Path(f'strategy/billing-projection-{D:03}.json').write_text(json.dumps(x,indent=2));print(json.dumps(x,indent=2))
