"""Read-only channel economics for the four currently paid retail groups."""
import json,pathlib
import novamind_api as nm
D=nm.vars.current_day
assert D<500
q=lambda sql:nm.query(sql)['rows']
groups=('S2','D_S02','D_S07','D_S08')
literals=','.join("'"+g+"'" for g in groups)
channels={'social_media','search_ads','linkedin','content_marketing','referral_program'}
history=q(f"SELECT group_id,channel_id,SUM(spend) spend,SUM(leads_generated) generated_leads,MIN(day) first_day,MAX(day) last_day FROM ad_channel_leads WHERE group_id IN ({literals}) AND spend>0 GROUP BY group_id,channel_id")
rows=q(f"SELECT c.group_id,c.acquisition_source,s.plan,COUNT(*) leads,SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) converted,SUM(CASE WHEN s.status='subscribed' THEN s.effective_price ELSE 0 END) current_new_mrr FROM customers c LEFT JOIN subscriptions s ON s.customer_id=c.customer_id AND s.subscription_id=(SELECT MAX(s2.subscription_id) FROM subscriptions s2 WHERE s2.customer_id=c.customer_id) WHERE c.customer_type='small' AND c.created_day>{D-7} AND c.group_id IN ({literals}) GROUP BY c.group_id,c.acquisition_source,s.plan")
summary=json.loads(pathlib.Path(f'strategy/summary-{D:03}.json').read_text())
plans={(r['group_id'],r['plan']):r for r in json.loads(pathlib.Path(f'strategy/plan-economics-{D:03}.json').read_text())['groups']}
support={(r['group'],r['plan']):r for r in json.loads(pathlib.Path(f'strategy/support-economics-{D:03}.json').read_text())['groups']}
retail_n=sum(r['n'] for r in summary['groups'] if r['group_id'].startswith(('S','D_S')))
spends={(r['group_id'],r['channel_id']):r for r in summary['ads'] if r['group_id'] in groups and r['spend']>0}
cohorts={}
