import json
from pathlib import Path
x=json.load(open('strategy/network-value-review-336.json'));econ={r['group_id']:r for r in json.load(open('strategy/acquisition-review-336.json'))['groups']}
def value(g,start,loss):
 days=501-start;s=1-loss;e=econ[g];bills=(days-1)//30+1
 return e['arpu']*sum(s**m for m in range(bills))-e.get('first_period_only_discount',0)-(e['arpu']-e['monthly_margin'])/30*sum(s**m*min(30,days-30*m) for m in range(bills))
rows=[]
for source in ['S1','S3']:
 for sl in [.25,.4,.55]:
  direct=sum(value(source,start,sl) for start in range(337,344))/7
  for tl in [.25,.4]:
   indirect=0
   for c in x['calibration']:
    g=c['destination']
    if g==source:continue
    rate=c['incoming'].get(source,0)*c['observed_to_nominal_ratio']
    if not rate:continue
    for start in range(337,344):
     for day in range(start+1,501):indirect+=rate*(1-sl)**((day-start)//30)/7*(c['conversion']*value(g,day,tl)-.5)
   rows.append(dict(source=source,source_loss=sl,target_loss=tl,direct=direct,indirect=indirect,quarter_effect=direct+.25*indirect))
print(json.dumps(rows,indent=1))
Path('strategy/additional-network-sensitivity-336.json').write_text(json.dumps({'day':336,'basis':'Saved public336network calibration and acquisition economics; same uncertain noncausal onegeneration sensitivity','scenarios':rows},indent=2))
PY"

