"""Read-only channel economics for the four currently paid retail groups."""
import json,pathlib
import novamind_api as nm
D=nm.vars.current_day
assert D<500
q=lambda sql:nm.query(sql)['rows']
groups=('S2','D_S02','D_S07','D_S08')
literals=','.join("'"+g+"'" for g in groups)
channels={'social_media','search_ads','linkedin','content_marketing','referral_program'}
history=q(f"SELECT group_id,channel_id,SUM(spend) spend,SUM(leads_generated) generated_leads,MIN(day) first_day,MAX(day) last_day FROM ad_channel_leads WHERE group_id IN ({literals}) AND spend>0 GROUP BY group_id,channel_id")
rows=q(f"SELECT c.group_id,c.acquisition_source,s.plan,COUNT(*) leads,SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) converted,SUM(CASE WHEN s.status='subscribed' THEN s.effective_price ELSE 0 END) current_new_mrr FROM customers c LEFT JOIN subscriptions s ON s.customer_id=c.customer_id AND s.subscription_id=(SELECT MAX(s2.subscription_id) FROM subscriptions s2 WHERE s2.customer_id=c.customer_id) WHERE c.customer_type='small' AND c.created_day>{D-7} AND c.group_id IN ({literals}) GROUP BY c.group_id,c.acquisition_source,s.plan")
summary=json.loads(pathlib.Path(f'strategy/summary-{D:03}.json').read_text())
plans={(r['group_id'],r['plan']):r for r in json.loads(pathlib.Path(f'strategy/plan-economics-{D:03}.json').read_text())['groups']}
support={(r['group'],r['plan']):r for r in json.loads(pathlib.Path(f'strategy/support-economics-{D:03}.json').read_text())['groups']}
retail_n=sum(r['n'] for r in summary['groups'] if r['group_id'].startswith(('S','D_S')))
spends={(r['group_id'],r['channel_id']):r for r in summary['ads'] if r['group_id'] in groups and r['spend']>0}
cohorts={}
def blank(g,source):
 return {'group':g,'source':source,'leads':0,'converted':0,'current_new_mrr':0,'converted_plan_mix':{},'monthly_compute_total':0,'monthly_issue_cost_total':0}
for r in rows:
 g=r['group_id'];source=r['acquisition_source'];key=(g,source)
 assert source in channels|{'network','word_of_mouth'}, 'Inspect unexpected public acquisition source'
 a=cohorts.setdefault(key,blank(g,source));a['leads']+=r['leads'];a['converted']+=r['converted'];a['current_new_mrr']+=r['current_new_mrr']
 if r['converted']:
  plan=r['plan'];a['converted_plan_mix'][plan]=a['converted_plan_mix'].get(plan,0)+r['converted']
  a['monthly_compute_total']+=r['converted']*plans[(g,plan)]['monthly_compute_per_seat']
  a['monthly_issue_cost_total']+=r['converted']*support[(g,plan)]['monthly_issue_resolution_cost_per_seat']
for key in spends:cohorts.setdefault(key,blank(*key))
service_days=[500-day+1 for day in range(D+1,min(D+7,500)+1)]
for key,a in cohorts.items():
 spend=spends.get(key,{});a['ad_spend']=spend.get('spend',0);a['reported_generated_leads']=spend.get('leads',spend.get('leads_generated',0));n=a['converted']
 a['conversion']=n/a['leads'] if a['leads'] else None
 a['cost_per_lead']=a['ad_spend']/a['leads'] if a['leads'] and a['ad_spend'] else None
 a['paid_cac']=(a['ad_spend']+.5*a['leads'])/n if n and a['ad_spend'] else None
 a['arpu']=a['current_new_mrr']/n if n else None
 a['monthly_compute']=a['monthly_compute_total']/n if n else None
 a['monthly_issue_cost']=a['monthly_issue_cost_total']/n if n else None
 a['breakeven_cac_through_500']={}
 if n:
  cost=a['monthly_compute']+1.2*a['monthly_issue_cost']+30*37500/max(1,retail_n)
  a['monthly_margin']=a['arpu']-cost
  # These four groups currently have no first-period lead discount.
  for loss in [0.0,.1,.25,.4]:
   survival=1-loss
   values=[a['arpu']*sum(survival**m for m in range((days-1)//30+1))-cost/30*sum(survival**(t//30) for t in range(days)) for days in service_days]
   a['breakeven_cac_through_500'][str(loss)]=sum(values)/len(values)
result={'day':D,'signup_window':[D-6,D],'next_advance_signup_days':[D+1,min(D+7,500)],'official_ad_history':history,'cohorts':list(cohorts.values()),'caveat':'Public source/plan cohorts in the last7days. Same-week channel contrasts control group/time imperfectly; spending levels, saturation and reputation can affect results. Historical channel averages are not current returns. Per-source plan mix weights public group-plan current usage/support; not source-specific historical compute. Finite cash scenarios assume unchanged prices/costs and zero first-period lead promotions for these4groups (confirmed through308; update if promotions change). No future bills after500. Pending longer-term retention is not yet measured; preserve a fixed trial window for later review. This script submits no campaign.'}
pathlib.Path(f'strategy/retail-channel-review-{D:03}.json').write_text(json.dumps(result,indent=2))
print(json.dumps(result,indent=2))

