import novamind_api as nm,json
# Ongoing group-plan coupons also apply to new leads. Posted plan prices
# lock on signup; changing coupons also changes bills on legacy price cohorts.
p=json.load(open('strategy/policy.json'))
desired={'global':0,'by_group':{'D_S03':5},'by_customer':p.get('promotion_by_customer',{}),'by_group_plan':p.get('promotion_group_plan',{})}
rows=nm.query("SELECT settings_json FROM config_overrides WHERE setting_type='promotion' ORDER BY id DESC LIMIT 1")['rows']
current=json.loads(rows[0]['settings_json']) if rows else {}
# Skip only if every requested scope is explicitly present and equal in the public snapshot.
if all(k in current and current[k]==v for k,v in desired.items()):
 print('UNCHANGED_RETAIL_PROMOTIONS',flush=True)
else:
 result=nm.pricing.set_promotion(global_promotion=desired['global'],by_group=desired['by_group'],by_customer=desired['by_customer'],by_group_plan=desired['by_group_plan'])
 print('promotion_policy',result,flush=True)

