import json
from pathlib import Path
for f in ['support-flow-364','retail-diagnostics-364','retail-channel-review-364','billing-projection-364']:
 p=Path('strategy/'+f+'.json')
 if not p.exists():print(f,'pending');continue
 d=json.loads(p.read_text());print(f)
 if f.startswith('support'):print('opened',d['opened']);print('resolved',d['resolved'])
 if f.startswith('retail-diagnostics'):
  from collections import defaultdict
  t=defaultdict(lambda:[0,0]);last=defaultdict(lambda:[0,0])
  for r in d['renewals']:
   a=t[r['group_id']];a[0]+=r['scheduled'];a[1]+=r['cancellations']
   if r['day']==364:a=last[r['group_id']];a[0]+=r['scheduled'];a[1]+=r['cancellations']
  print('weekly',dict(t));print('latest',dict(last))
 if f.startswith('retail-channel'):
  for r in d['cohorts']:
   if r.get('paid_cac'): print(r['group'],r['source'],r['converted'],round(r['paid_cac'],1),round(r['monthly_margin'],1),r['breakeven_cac_through_500'])
 if f.startswith('billing'):print(d['totals'])
