{
  "/workspace/local/workspace/run-ceobench/strategy/review_digest.py": {
    "type": "add",
    "content": """"Print compact sections from saved public observation reports. No SDK calls."""
import json, sys
from pathlib import Path

D = int(sys.argv[1])
section = sys.argv[2] if len(sys.argv) > 2 else 'core'
root = Path('strategy')

def read(stem):
    p = root / f'{stem}-{D:03}.json'
    return json.loads(p.read_text()) if p.exists() else None

def show(label, value):
    print(label, json.dumps(value, separators=(',', ':')))

def selected(row, keys):
    return {key: row[key] for key in keys if key in row}

if section == 'core':
    summary = read('summary')
    show('HEADLINE', selected(summary, ['day', 'cash', 'flows', 'usage', 'macro']))
    for row in summary['groups']:
        show('BOOK', row)
    show('OLD_ISSUES', [r for r in summary['issues'] if r['age'] > 1])
    detail = read('detail')
    show('SERVICE', detail['service'])
    show('RESEARCH', detail['research'])
    quality = read('dashboard-quality')
    show('QUALITY', selected(quality, ['base_quality', 'shared_bonus', 'groups']))
    show('SUPPORT_FLOW', selected(read('support-flow'), ['opened', 'resolved', 'backlog']))
    show('BILLING', read('billing-projection')['totals'])
    show('RETENTION', read('retention-cohorts-review')['totals'])
    for row in read('renewal-exposure')['weeks']:
        if row['week_end'] == D:
            show('RENEWAL', row)
    for row in read('plan-economics')['groups']:
        if row['customer_type'] == 'small':
            show('RETAIL_PLAN', selected(row, ['group_id', 'plan', 'n', 'new_n', 'monthly_revenue_per_seat', 'monthly_compute_per_seat', 'monthly_after_compute']))
    for row in read('support-economics')['groups']:
        if row['group'].startswith(('S', 'D_S')):
            show('RETAIL_SUPPORT', row)
    for row in read('retail-channel-review')['cohorts']:
        show('CHANNEL', row)
    show('NEWS', summary['news'])
elif section == 'trials':
    stems = ['retail-channel-trial-review', 'retail-channel-trial-329-review',
             'retail-channel-trial-343-review', 'retail-channel-trial-364-review',
             'legacy-b-coupon-review', 'coupon-review-329-at', 'coupon-review-336-at',
             'premium-B-review', 'premium-enterprise-review-350-at',
             'retail-premium-review', 'retail-premium-phase-357-review',
             'premium-upsell-review']
    for stem in stems:
        report = read(stem)
        if report:
            show(stem, {key: value for key, value in report.items()
                        if key in ['day', 'groups', 'cohorts', 'paired_estimates',
                                   'first_renewals_fully_mature', 'second_renewals_fully_mature']})
else:
    raise SystemExit('section must be core or trials')
