"""Print compact sections from saved public observation reports. No SDK calls."""
import json, sys
from pathlib import Path

D = int(sys.argv[1])
section = sys.argv[2] if len(sys.argv) > 2 else 'core'
root = Path('strategy')

def read(stem):
    p = root / f'{stem}-{D:03}.json'
    return json.loads(p.read_text()) if p.exists() else None

def show(label, value):
    print(label, json.dumps(value, separators=(',', ':')))

def selected(row, keys):
    return {key: row[key] for key in keys if key in row}

if section == 'core':
    summary = read('summary')
    show('HEADLINE', selected(summary, ['day', 'cash', 'flows', 'usage', 'macro']))
    for row in summary['groups']:
        show('BOOK', row)
    show('OLD_ISSUES', [r for r in summary['issues'] if r['age'] > 1])
    detail = read('detail')
    show('SERVICE', detail['service'])
    show('RESEARCH', detail['research'])
    quality = read('dashboard-quality')
    show('QUALITY', selected(quality, ['base_quality', 'shared_bonus', 'groups']))
    show('SUPPORT_FLOW', selected(read('support-flow'), ['opened', 'resolved', 'backlog']))
    show('BILLING', read('billing-projection')['totals'])
    show('RETENTION', read('retention-cohorts-review')['totals'])
    for row in read('renewal-exposure')['weeks']:
        if row['week_end'] == D:
            show('RENEWAL', row)
    for row in read('plan-economics')['groups']:
        if row['customer_type'] == 'small':
            show('RETAIL_PLAN', selected(row, ['group_id', 'plan', 'n', 'new_n', 'monthly_revenue_per_seat', 'monthly_compute_per_seat', 'monthly_after_compute']))
    for row in read('support-economics')['groups']:
        if row['group'].startswith(('S', 'D_S')):
            show('RETAIL_SUPPORT', row)
    for row in read('retail-channel-review')['cohorts']:
        show('CHANNEL', row)
    show('NEWS', summary['news'])
elif section == 'trials':
    stems = ['retail-channel-trial-review', 'retail-channel-trial-329-review',
             'retail-channel-trial-343-review', 'retail-channel-trial-364-review', 'retail-channel-trial-371-review',
             'legacy-b-coupon-review', 'coupon-review-329-at', 'coupon-review-336-at',
             'premium-B-review', 'premium-enterprise-review-350-at',
             'retail-premium-review', 'retail-premium-phase-357-review',
             'premium-upsell-review']
    for stem in stems:
        report = read(stem)
        if report:
            show(stem, {key: value for key, value in report.items()
                        if key in ['day', 'groups', 'cohorts', 'paired_estimates',
                                   'first_renewals_fully_mature', 'second_renewals_fully_mature']})
else:
    raise SystemExit('section must be core or trials')
"""Read-only public daily acquisition results for current retail campaigns."""
import json
from pathlib import Path
import novamind_api as nm

D=nm.vars.current_day
assert 378<=D<500
q=lambda sql:nm.query(sql)['rows']
groups=('S1','S2','S3','D_S09','D_S10')
sql_groups=','.join("'"+g+"'" for g in groups)
spend=q(f"SELECT day,group_id,channel_id,SUM(spend) spend,SUM(leads_generated) leads_generated FROM ad_channel_leads WHERE day>{D-7} AND group_id IN ({sql_groups}) AND spend>0 GROUP BY day,group_id,channel_id")
rows=q(f"SELECT c.created_day day,c.group_id,c.acquisition_source channel_id,s.plan,COUNT(*) leads,SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) converted,SUM(CASE WHEN s.status='subscribed' THEN s.effective_price ELSE 0 END) new_mrr FROM customers c LEFT JOIN subscriptions s ON s.customer_id=c.customer_id AND s.subscription_id=(SELECT MAX(s2.subscription_id) FROM subscriptions s2 WHERE s2.customer_id=c.customer_id) WHERE c.customer_type='small' AND c.created_day>{D-7} AND c.group_id IN ({sql_groups}) AND c.acquisition_source NOT IN ('network','word_of_mouth') GROUP BY c.created_day,c.group_id,c.acquisition_source,s.plan")
plans={(r['group_id'],r['plan']):r for r in json.loads(Path(f'strategy/plan-economics-{D:03}.json').read_text())['groups']}
support={(r['group'],r['plan']):r for r in json.loads(Path(f'strategy/support-economics-{D:03}.json').read_text())['groups']}
out={}
for r in spend:
 out[(r['day'],r['group_id'],r['channel_id'])]={**r,'leads':0,'converted':0,'new_mrr':0.,'monthly_compute_estimate':0.,'monthly_support_allowance':0.,'plan_mix':{}}
for r in rows:
 key=(r['day'],r['group_id'],r['channel_id'])
 a=out.setdefault(key,{'day':r['day'],'group_id':r['group_id'],'channel_id':r['channel_id'],'spend':0.,'leads_generated':0,'leads':0,'converted':0,'new_mrr':0.,'monthly_compute_estimate':0.,'monthly_support_allowance':0.,'plan_mix':{}})
 a['leads']+=r['leads'];a['converted']+=r['converted'];a['new_mrr']+=r['new_mrr']
 if r['converted']:
  plan=r['plan'];a['plan_mix'][plan]=a['plan_mix'].get(plan,0)+r['converted']
  a['monthly_compute_estimate']+=r['converted']*plans[(r['group_id'],plan)]['monthly_compute_per_seat']
  a['monthly_support_allowance']+=r['converted']*support[(r['group_id'],plan)]['monthly_issue_resolution_cost_per_seat']
for a in out.values():
 a['cac']=(a['spend']+.5*a['leads'])/a['converted'] if a['converted'] else None
 a['first_30day_contribution_less_acquisition_estimate']=a['new_mrr']-a['monthly_compute_estimate']-1.2*a['monthly_support_allowance']-a['spend']-.5*a['leads']
 a['arpu']=a['new_mrr']/a['converted'] if a['converted'] else None
result={'day':D,'rows':sorted(out.values(),key=lambda r:(r['group_id'],r['channel_id'],r['day'])),
        'caveat':'Public actual daily ad spending, created-day source cohorts and current subscription status; this is not a causal channel comparison. Month-cost estimates use current group-plan averages and a20percent support allowance, not individual historical costs. These monitored groups have no lead-only discount under confirmed current policy. Common capacity/development excluded. Last-day results may be noisy; no spend decisions or automatic changes are made.'}
assert nm.vars.current_day==D
Path(f'strategy/retail-channel-daily-{D:03}.json').write_text(json.dumps(result,indent=2))
print('DAILY_CHANNEL_REVIEW',D,len(result['rows']),flush=True)

