oldads=adcfg.get('targeted_spend',adcfg)
oldgroup={}
for ch,gs in oldads.items():
 if isinstance(gs,dict):
  for g,v in gs.items():oldgroup[g]=oldgroup.get(g,0)+float(v)
co=q(f"SELECT c.group_id,COUNT(*) leads,SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) converted,SUM(CASE WHEN s.status='subscribed' THEN s.effective_price ELSE 0 END) new_mrr,SUM(CASE WHEN c.acquisition_source NOT IN ('network','word_of_mouth') AND s.status='subscribed' THEN 1 ELSE 0 END) paid_converted,SUM(CASE WHEN c.acquisition_source NOT IN ('network','word_of_mouth') THEN 1 ELSE 0 END) paid_leads FROM customers c JOIN subscriptions s USING(customer_id) WHERE c.created_day>{D-7} AND c.customer_type='small' GROUP BY c.group_id")
co={r['group_id']:r for r in co}
book={r['group_id']:r for r in x['groups']}
retail={g:r for g,r in book.items() if g.startswith('S') or g.startswith('D_S')}
n=sum(r['n'] for r in retail.values())
new=sum(r['new'] for r in retail.values())
flows={r['category']:r['amount'] for r in x['flows']}
usage=q(f"SELECT c.group_id,SUM(u.usage_units*CASE s.plan WHEN 'A' THEN {dict([(1,.0003),(2,.002),(3,.006),(4,.012),(5,.03)])[cfg['tier_A']]} WHEN 'B' THEN {dict([(1,.0003),(2,.002),(3,.006),(4,.012),(5,.03)])[cfg['tier_B']]} ELSE {dict([(1,.0003),(2,.002),(3,.006),(4,.012),(5,.03)])[cfg['tier_C']]} END) cost FROM daily_usage u JOIN customers c USING(customer_id) JOIN subscriptions s USING(customer_id) WHERE u.day={D} AND s.status='subscribed' GROUP BY c.group_id")
uc={r['group_id']:r['cost'] for r in usage}
observed_ads={}
for r in x['ads']:observed_ads[r['group_id']]=observed_ads.get(r['group_id'],0)+r['spend']
plan_projection={}
