"""Pure strategy helper: preserve retail referrals and expire extra campaigns."""
import math

def build_ad_plan(day,primary_referrals,campaigns,budget):
    """Campaign windows use decision days: [294,301) funds days295..301."""
    assert math.isfinite(budget) and budget>=0
    allowed={'social_media','search_ads','linkedin','content_marketing','referral_program'}
    primary=dict(primary_referrals)
    assert all(math.isfinite(v) and v>=0 for v in primary.values())
    additional={};active=[];seen=set()
    for campaign in campaigns:
        start=campaign['start_day'];end=campaign['end_day']
        assert isinstance(start,int) and isinstance(end,int) and 0<=start<end<=500
        assert start%7==0 and (end%7==0 or end==500), 'Campaign windows must align to game decision days'
        assert campaign['campaign_id'] not in seen, 'Duplicate campaign ID'
        seen.add(campaign['campaign_id'])
        if not start<=day<end:continue
        active.append(campaign['campaign_id'])
        for channel,groups in campaign['spend'].items():
            assert channel in allowed
            for group,amount in groups.items():
                assert math.isfinite(amount) and 0<=amount<=1e12
                if amount:
                    additional.setdefault(channel,{})
                    additional[channel][group]=additional[channel].get(group,0)+amount
    extra_total=sum(sum(groups.values()) for groups in additional.values())
    assert extra_total<=budget, 'Campaign spend exceeds the total ad budget; no mutation submitted'
    available=budget-extra_total
    if sum(primary.values())>available:
        factor=available/sum(primary.values())
        primary={g:math.floor(v*factor/1000)*1000 for g,v in primary.items() if v*factor>=1000}
    plan={'referral_program':primary.copy()}
    for channel,groups in additional.items():
        plan.setdefault(channel,{})
        for group,amount in groups.items():plan[channel][group]=plan[channel].get(group,0)+amount
    total=sum(sum(groups.values()) for groups in plan.values())
    assert total<=budget+1e-8
    return primary,plan,total,active
