def value(g,signup,loss):
 days=500-signup+1;e=econ[g];price=e['arpu'];cost=price-e['monthly_margin'];s=1-loss;bills=(days-1)//30+1
 return price*sum(s**m for m in range(bills))-e.get('first_period_only_discount',0)-cost/30*sum(s**m*min(30,days-30*m) for m in range(bills))
results=[]
for source in ['D_S06','D_S04','D_S05','D_S08']:
 for sl in [.25,.40,.55]:
  for tl in [.10,.25,.40]:
   direct=sum(value(source,start,sl) for start in range(D+1,D+8))/7;indirect=0.
   for c in coeff:
    if c['destination']==source:continue
    rate=c['incoming'].get(source,0)*c['observed_to_nominal_ratio']
    for start in range(D+1,D+8):
     for day in range(start+1,501):
