\"\"\"Compact saved-public-observation digest. No simulator calls or actions.
Usage: python strategy/weekly_brief.py DAY [core|trials]
All derived costs are forward allowances, not individual collected cash.
\"\"\"
import json,sys,collections
from pathlib import Path
D=int(sys.argv[1]); section=sys.argv[2] if len(sys.argv)>2 else 'core';root=Path('strategy')
def read(stem):
 p=root/f'{stem}-{D:03}.json'
 return json.loads(p.read_text()) if p.exists() else None
def show(label,x):print(label,json.dumps(x,separators=(',',':')))
def pick(x,keys):return {k:x[k] for k in keys if k in x}
def slim(x):
 if isinstance(x,float):return round(x,3)
 if isinstance(x,list):return [slim(v) for v in x]
 if isinstance(x,dict):return {k:slim(v) for k,v in x.items()}
 return x
if section=='core':
 s=read('summary');detail=read('detail');bill=read('billing-projection');quality=read('dashboard-quality')
 assert s['day']==D
 show('CASH_FLOWS',pick(s,['day','cash','flows','macro']))
 show('QUALITY',pick(quality,['base_quality','shared_bonus']))
 show('SERVICE',slim(detail['service']))
 show('RESEARCH',slim(detail['research']))
 show('ISSUE_FLOW',read('support-flow')['opened'])
 show('OLDER_OPEN_ISSUES',[r for r in s['issues'] if r['age']>0])
 show('BILLING',slim(bill['totals']))
 show('ENTERPRISE_RESCUE',slim(read('retention-cohorts-review')['totals']))
 losses={r['group_id']:r['cancel_per_scheduled_renewal'] for r in read('renewal-exposure')['weeks'] if r['week_end']==D}
 support={(r['group'],r['plan']):r['monthly_issue_resolution_cost_per_seat'] for r in read('support-economics')['groups']}
 plans=read('plan-economics')['groups'];group_bills=collections.defaultdict(float)
 for r in bill['groups']:group_bills[r['group_id']]+=r['projected_scheduled_7d']
 for r in s['groups']:
  g=r['group_id'];a={**r,'next7_scheduled':group_bills[g]}
  if g in losses:a['aggregate_renewal_loss']=losses[g]
  show('BOOK',slim(a))
 for r in plans:
  if r['customer_type']"'!='"'small':continue
  a=pick(r,['group_id','plan','n','new_n','monthly_revenue_per_seat','monthly_compute_per_seat']);a['monthly_support_per_seat']=support[(r['group_id'],r['plan'])]
  show('RETAIL_PLAN',slim(a))
 daily=read('retail-channel-daily');recent=collections.defaultdict(lambda:collections.defaultdict(float))
 if daily:
  for r in daily['rows']:
   if r['day']<=D-3:continue
   a=recent[(r['group_id'],r['channel_id'])]
   for k in ['spend','leads','converted','new_mrr','first_30day_contribution_less_acquisition_estimate']:a[k]+=r[k]
 for r in read('retail-channel-review')['cohorts']:
  if not r['ad_spend']:continue
  a=pick(r,['group','source','leads','converted','paid_cac','arpu','monthly_margin','breakeven_cac_through_500']);z=recent.get((r['group'],r['source']))
  if z:a['latest3days']={**z,'cac':(z['spend']+.5*z['leads'])/z['converted'] if z['converted'] else None}
  show('CHANNEL',slim(a))
 show('RIVAL_NEWS',s['news'])
elif section=='trials':
 for stem in ['retail-channel-trial-review','retail-channel-trial-329-review','retail-channel-trial-343-review','retail-channel-trial-364-review','retail-channel-trial-371-review']:
  x=read(stem)
  if not x:continue
  show(stem,pick(x,['first_renewals_fully_mature','second_renewals_fully_mature']))
  for r in x['cohorts']:
   show('AD_COHORT',slim(pick(r,['group','source','initial_subscribers','current_active','matured_first_renewals','first_renewal_loss_rate','matured_second_renewals','cumulative_second_renewal_loss_rate','initial_paid_cac'])))
 for stem in ['retail-premium-review','retail-premium-phase-357-review']:
  x=read(stem)
  if not x:continue
  for r in x['cohorts']:
   show(stem,slim(pick(r,['cohort','group','initial_accounts','active','first_bill_matured','second_bill_matured','projected_next_bill_after_compute','projected_negative_after_compute','active_usage_days_below5'])))
 for stem in ['premium-upsell-review','premium-upsell-378-review']:
  x=read(stem)
  if not x:continue
  for r in x['groups']:
   show(stem,slim(pick(r,['group','treatment','initial_accounts','active_accounts','A','B','C','monthly_after_compute_support_allowance','accepted_original_seller_thread','open_original_seller_thread','open_retention_accounts','retention_exposed_mrr','negative_active','short_active_usage'])))
  show('PAIRED',slim(x['paired_estimates']))
 for stem in ['legacy-b-coupon-review','coupon-review-329-at','coupon-review-336-at']:
