"""Print bounded progress from our own public CLI stdout artifact only."""
import json,sys
from pathlib import Path
day=int(sys.argv[1]);assert 0<=day<=500
p=Path(f'strategy/turn-{day:03}.out')
lines=p.read_text().splitlines() if p.exists() else []
for line in lines:
 if line.startswith('WEEKLY_ANALYSIS '):
  x=json.loads(line.split(' ',1)[1]);print('BUDGETS',json.dumps({k:x[k] for k in ['day','ad_total','operations','enterprise_ops']}))
 elif line.startswith('{"request_id"') or line.startswith(('deal_errors','offers ','new_enterprise_quality_menus','premium_C_seller_replies','premium_seller_pilot_replies','RESULT_KEYS','CONFIRMED_DAY','Traceback','AssertionError')): print(line[:600])
 elif line.startswith('ADVANCE_PLAN '):print('ADVANCE_PLAN_PREPARED')
if lines:print('LAST_STDOUT',lines[-1][:250])
else:print('No stdout yet; initial public observations still running.')

