"""Public follow-up of day350 group B offers; no game mutations."""
import json
from pathlib import Path
import novamind_api as nm
D=nm.vars.current_day
START=globals().get('TRIAL_START',350)
assert START+7<=D<500
q=lambda sql:nm.query(sql)['rows']
path=Path(f'strategy/retail-premium-trial-{START}.json' if START==350 else f'strategy/retail-premium-phase-{START}.json');trial=json.loads(path.read_text())
assert trial['status']=='confirmed'
groups=','.join("'"+g+"'" for g in trial['prices'])
baseline_B={r['customer_id'] for r in trial['baseline_B']}
if 'first_week_B_snapshot' not in trial:
 assert D==START+7, 'First adopter snapshot must be captured at the first review; never reconstruct an earlier turn.'
 members=[];last=0
 while True:
  rows=q(f"SELECT c.group_id,c.created_day,s.customer_id,s.listed_price,s.effective_price,s.billing_day_mod30 FROM customers c JOIN subscriptions s USING(customer_id) WHERE c.group_id IN ({groups}) AND c.customer_type='small' AND s.status='subscribed' AND s.plan='B' AND s.customer_id>{last} ORDER BY s.customer_id LIMIT 1000")
  for r in rows:
   if r['customer_id'] not in baseline_B:
    r['first_followup_bill_day']=D+((r['billing_day_mod30']-D%30+30)%30 or 30)
    members.append(r)
