"""Compact saved-public-observation digest. No simulator calls or actions.
Usage: python strategy/weekly_brief.py DAY [core|trials]
All derived costs are forward allowances, not individual collected cash.
"""
import json,sys,collections
from pathlib import Path
D=int(sys.argv[1]); section=sys.argv[2] if len(sys.argv)>2 else 'core';root=Path('strategy')
def read(stem):
 p=root/f'{stem}-{D:03}.json'
 return json.loads(p.read_text()) if p.exists() else None
def show(label,x):print(label,json.dumps(x,separators=(',',':')))
def pick(x,keys):return {k:x[k] for k in keys if k in x}
def slim(x):
 if isinstance(x,float):return round(x,3)
 if isinstance(x,list):return [slim(v) for v in x]
 if isinstance(x,dict):return {k:slim(v) for k,v in x.items()}
 return x
if section=='core':
 s=read('summary');detail=read('detail');bill=read('billing-projection');quality=read('dashboard-quality')
 assert s['day']==D
 show('CASH_FLOWS',pick(s,['day','cash','flows','macro']))
 show('QUALITY',pick(quality,['base_quality','shared_bonus']))
