"""Pure helpers for exact original C25 pilot threads; no API calls."""
import json,math
from pathlib import Path
def load_pilots():
 out={}
 for p in Path('strategy').glob('C25-efficiency-pilot-[0-9][0-9][0-9].json'):
  x=json.loads(p.read_text())
  if x['status']!='completed':continue
  successful={r['customer_id'] for r in x.get('result',{}).get('results',[]) if r.get('success')}
  for r in x['customers']:
   tid=x.get('pilot_thread_ids',{}).get(str(r['customer_id']))
   if r['treatment'] and r['customer_id'] in successful and tid is not None:out[(r['customer_id'],tid)]=r
 return out
def decide(pilot,current,units,days,cfg,requested,counter):
 result={'offerings':[],'C_floor':None,'decision':'close_ineligible_seller_preserve_contract'}
 if not(current.get('plan')=='B' and abs(current.get('effective_price',-1)-pilot['effective_price'])<.001 and current.get('pending_plan') is None and current.get('pending_price') is None and days>=5 and cfg['tier_B']==4 and cfg['tier_C']==5):return result
 per_seat=units/max(1,current['seat_count']);full_C=.03*30*cfg['quota_C']
 floor=max(1.2*full_C+5,current['effective_price']-30*per_seat*.012+full_C+3)
 result['C_floor']=floor
 if requested=='C' and counter is not None:
  if min(counter,pilot['offered_C'])>=floor:result.update(offerings=[['C',math.ceil(min(counter,pilot['offered_C'])*100)/100]],decision='C_counter_covers_fullquota_and_current_contribution')
  else:result['decision']='close_C_counter_below_floor_preserve_contract'
 elif requested=='B' and counter is not None:
  if min(counter,pilot['offered_B'])>=current['effective_price']*1.02:result.update(offerings=[['B',math.ceil(min(counter,pilot['offered_B'])*100)/100]],decision='bounded_B_uplift_still_may_be_compute_negative')
  else:result['decision']='close_B_counter_without_uplift_preserve_contract'
 elif requested not in ('A',):
  offers=[['B',pilot['offered_B']]]
  if pilot['offered_C']>=floor:offers.insert(0,['C',pilot['offered_C']])
  result.update(offerings=offers,decision='repeat_reviewed_menu_with_current_C_floor')
 return result

"""Offline fixed assignment from completed public455 preflight; no API."""
import collections,hashlib,json,math
from pathlib import Path
p=Path('strategy/C25-efficiency-pilot-455.json');assert not p.exists()
x=json.loads(Path('strategy/negative-B-history-455.json').read_text());assert x['day']==455
groups=collections.defaultdict(list)
for r in x['customers']:
 if r['eligible_for_bounded_pilot_review']:groups[r['group_id']].append(r)
members=[];pair=0
for g,rows in sorted(groups.items()):
 rows.sort(key=lambda r:(-r['seat_count'],r['customer_id']))
 for i in range(0,len(rows)-1,2):
  a,b=rows[i:i+2];pair+=1
  treated=int(hashlib.sha256(f'C25-455-{g}-{a["customer_id"]}-{b["customer_id"]}'.encode()).hexdigest(),16)%2
  for j,r in enumerate((a,b)):
   members.append({**r,'pair_id':pair,'treatment':j==treated,'offered_C':max(32,r['effective_price']),'offered_B':math.ceil(105*r['effective_price'])/100,'baseline_monthly_support_allowance':r['last14_new_issues']*30/14/.05})
assert len(members)==20 and sum(r['treatment'] for r in members)==10
trial={'day':455,'status':'prepared','customers':members,'followup_required':True,'followup_through':497,'selection':'>=2full7dayusagewindows afterlastacceptedthread, every eligiblewindowcompute>=105percentcurrentrevenue; currentB,noopen/pending,nooldpilotmember. Pairwithingroupbydescendingseatcount, salt-hashassignmentwithinpair, dropunpairedtail. Currentseatcountdenominator/historicusage comparison imperfect.','caveat':'Smallselectedmatchedexperiment, notpopulationestimate. C25samecurrentfee(min32), Bfallback+5percent; Bfallback improvesfeesbutmayremaincompute-negative. Ccounterfloorcoversfullquota plusbuffer andcurrentBcontribution. Customer mayreject lowquota orlaterchurn. Failedsellerpreservesexistingterms. No signing-day cash assumed. Measure originalthread,actualplan/usage/payments and controls through497; neverextend500.'}
p.write_text(json.dumps(trial,indent=2))
print('C25_PILOT_PREPARED',len(members),'treated',sum(r['treatment'] for r in members),'treated_seats',sum(r['seat_count'] for r in members if r['treatment']),flush=True)

"""Public followup of the fixed455 C25 seller trial; no mutations."""
import json,math,statistics
from pathlib import Path
import novamind_api as nm
D=nm.vars.current_day;assert 462<=D<=500
p=Path('strategy/C25-efficiency-pilot-455.json');trial=json.loads(p.read_text());assert trial['status']=='completed'
q=lambda s:nm.query(s)['rows']
members=trial['customers'];ids=','.join(str(r['customer_id']) for r in members)
cfg=q('SELECT * FROM config_history ORDER BY day DESC LIMIT 1')[0];rates={1:.0003,2:.002,3:.006,4:.012,5:.03}
