 if spend>=1000:chosen[g]=round(spend/1000)*1000
 analysis.append({'group':g,'conversion':round(conv,3),'arpu':round(arpu,1),'gross_monthly_margin':round(monthly_margin,1),'margin_basis':plan_projection.get(g,{}).get('basis','legacy_mixed_book_fallback'),'monthly_compute':round(plan_projection[g]['compute'],1) if g in plan_projection else None,'monthly_issue_resolution':round(plan_projection[g]['support'],1) if g in plan_projection else None,'paid_cac':round(cac,1) if oldspend else None,'old_ad':oldspend,'new_ad':spend})
for g,v in policy.get('ad_overrides',{}).items():
