"""Execute an explicitly reviewed restart plan once, through the public SDK.

Requires strategy/research-plan.json containing expected_day, tiers and reason.
Never rerun after a start marker exists; inspect the printed request IDs instead.
"""
import json
from pathlib import Path
import novamind_api as nm

plan = json.loads(Path('strategy/research-plan.json').read_text())
day = nm.vars.current_day
assert day == plan['expected_day'] and day < 500
tiers = plan['tiers']
assert tiers and len(tiers) == len(set(tiers))
assert all(type(t) is int and 1 <= t <= 10 for t in tiers)
assert isinstance(plan.get('reason'), str) and plan['reason'].strip()
dest = Path(f'strategy/research-{day:03}.json')
assert not dest.exists(), 'Research already started: check request status, never replay.'
rows = nm.query('SELECT tier,status FROM research_projects')['rows']
assert not any(r['tier'] in tiers and r['status'] == 'in_progress' for r in rows)
assert all(any(r['tier'] == t and r['status'] == 'completed' for r in rows) for t in tiers)
state = {'day': day, 'status': 'submitting', 'plan': plan, 'results': [], 'pending_tier': None}
dest.write_text(json.dumps(state, indent=2))
for tier in tiers:
    state['pending_tier'] = tier
    dest.write_text(json.dumps(state, indent=2))
    result = nm.research.start_research_project(tier=tier)
    assert 'project_id' in result, result
    state['results'].append(result)
    state['pending_tier'] = None
    dest.write_text(json.dumps(state, indent=2))
    print(result, flush=True)
assert nm.vars.current_day == day
state['status'] = 'completed'
dest.write_text(json.dumps(state, indent=2))

